={{ (() => {
  const t = $json.message?.text || "";
  const low = t.toLowerCase();
  const tags = [];

  const flowRequested = /\/engine\s*(flow|gemini)|используй\s*(flow|флоу|gemini|гугл|google)|сделай\s+на\s*(flow|флоу)|через\s*(flow|флоу|gemini|гугл|google)|на\s*флоу/.test(low);
  const pollinationsRequested = /\/engine\s*pollinations|используй\s*pollinations|через\s*pollinations|на\s*pollinations/.test(low);
  const directImageRequest = /(сделай|создай|сгенерируй|нарисуй|подготовь)\s+.*(фото|картин|изображ|аватар)/.test(low);
  const directVideoRequest = /(сделай|создай|сгенерируй|запусти)\s+.*(видео|ролик)/.test(low);

  if (flowRequested) {
    tags.push("FLOW_FORCE");
    tags.push("ENGINE_LOCK_FLOW");
  }
  if (pollinationsRequested) {
    tags.push("POLLINATIONS_FORCE");
    tags.push("ENGINE_LOCK_POLLINATIONS");
  }

  if (directImageRequest && !pollinationsRequested && !flowRequested) {
    tags.push("FLOW_FORCE");
    tags.push("ENGINE_LOCK_FLOW");
  }

  if (/подтверждаю фото/.test(low) || directImageRequest) tags.push("CONFIRM_PHOTO_FORCE");
  if (/подтверждаю видео/.test(low) || directVideoRequest) tags.push("CONFIRM_VIDEO_FORCE");
  if (/не нравится|переделай|сделай другую|другой вариант|заново/.test(low)) tags.push("REGENERATE_FORCE");
  if (/сбрось контекст|начнем заново|начнём заново|reset context/.test(low)) tags.push("RESET_CONTEXT_FORCE");
  if (/продолжить|continue/.test(low)) tags.push("CONTINUE_FORCE");

  tags.push("NO_REFUSAL_MODE");

  return tags.length ? (t + "\n[" + [...new Set(tags)].join("|") + "]") : t;
})() }}

