const input = $input.first().json || {};
const ownerIds = ['7326497224'];

const chatId = String(input?.message?.chat?.id || '');
const userId = String(input?.message?.from?.id || '');

const authorized = ownerIds.includes(chatId) || ownerIds.includes(userId);

return [{
  json: {
    ...input,
    auth_status: authorized ? 'allow' : 'deny',
    auth_meta: {
      chat_id: chatId,
      user_id: userId,
      owner_ids: ownerIds,
    },
  },
}];

const j = $input.first().json || {};
const original = String(j.output || j.text || '').trim();
const srcText = String(j.text || '').replace(/\n\[[^\]]+\]\s*$/,'').trim();

const refusalRe = /(извините\s*,?\s*но.*не могу|не могу помочь|не могу выполнить|нет доступа к (необходимым )?инструментам|контент не подходит|запрос не может быть выполнен)/i;
const loopRe = /(уточни,? что сейчас делаем|мы создаем фото\.?\s*что должно быть на фото\??|что должно быть на фото\??|выбери цель: фото или видео)/i;

if (refusalRe.test(original)) {
  const fallback = [
    'Сделаем. Помогу переформулировать запрос так, чтобы картинка точно получилась.',
    'Напиши в одной фразе: объект + стиль + настроение + формат (например: "аватар бота, киберпанк, неоновый, 1:1 png").',
    'Если хочешь, сразу запущу через Flow. Если не получится, аккуратно переключу на Pollinations без потери контекста.'
  ].join(' ');

  return [{
    json: {
      ...j,
      output: fallback,
      guardrail_refusal_rewritten: true,
      original_output: original,
    },
  }];
}

if (loopRe.test(original)) {
  const subject = srcText || 'твою идею';
  const fallback = 'Принял. Делаю сразу по запросу: "' + subject + '". Запускаю генерацию фото через Flow. Если хочешь другой движок, напиши: /engine pollinations.';
  return [{
    json: {
      ...j,
      output: fallback,
      guardrail_loop_rewritten: true,
      original_output: original,
    },
  }];
}

return [{ json: j }];

const input = $input.first().json || {};
const text = String(input.query || input.text || input.message || '').trim();
const low = text.toLowerCase();

const hasAny = (arr) => arr.some((s) => low.includes(s));

const isGreeting = !text || /^(\/start|start|старт|привет|хай|hello|hi|здарова|добрый)/i.test(low);
const isEngineCmd = /\/engine\s*(flow|gemini|pollinations)/i.test(text) || hasAny([
  'движок', 'engine', 'на флоу', 'через flow', 'через флоу', 'через гугл', 'через google', 'через gemini',
  'через pollinations', 'на pollinations', 'pollinations',
]);
const isConfig = /\/flowcfg\b/i.test(text) || hasAny([
  'model:', 'модель:', 'aspect ratio', 'соотношение', 'output resolution', 'разрешение',
  'output format', 'формат', 'person generation', 'персонажи', 'люди',
]);
const isRegen = hasAny(['не нравится', 'переделай', 'другой вариант', 'заново']);
const isConfirmVideo = hasAny(['подтверждаю видео', 'делай видео', 'генерируй видео']);
const isConfirmPhoto = hasAny(['подтверждаю фото', 'делай фото', 'генерируй фото']);
const isImageRequest = hasAny(['фото', 'картин', 'изображ', 'аватар', 'открытк', 'постер', 'иллюстрац', 'сделай', 'создай', 'нарисуй']);

let intent = 'free_message';
if (isGreeting) intent = 'greeting';
else if (isEngineCmd) intent = 'engine_select';
else if (isConfig) intent = 'config_update';
else if (isRegen) intent = 'regenerate';
else if (isConfirmVideo) intent = 'confirm_video';
else if (isConfirmPhoto) intent = 'confirm_photo';
else if (isImageRequest) intent = 'image_request';

let engine = String(input.engine || '').toLowerCase();
if (!engine) {
  if (/\/engine\s*(flow|gemini)/i.test(text) || hasAny(['используй flow', 'используй флоу', 'используй gemini', 'движок флоу', 'flow', 'флоу'])) engine = 'flow';
  if (/\/engine\s*pollinations/i.test(text) || hasAny(['движок pollinations', 'pollinations'])) engine = 'pollinations';
}

const mode = ['image_request', 'confirm_photo', 'regenerate', 'confirm_video'].includes(intent)
  ? 'generation'
  : 'dialog';

const hint = mode === 'generation'
  ? 'Пользователь ожидает действие, не застревай в опросе.'
  : 'Свободный диалог, при необходимости 1 короткий уточняющий вопрос.';

const routedText = text + '\n[INTENT:' + intent + '|ENGINE_PREF:' + (engine || 'auto') + '|MODE:' + mode + ']' + '\nROUTER_HINT: ' + hint;

return [{
  json: {
    ...input,
    intent,
    engine_preference: engine || '',
    mode,
    routed_text: routedText,
    source: 'intent-router-linear-v1',
  },
}];

